// disposeResult applies the JetStream action for a sync result and records the
// outcome metrics. elapsed is the wall-time of the sync attempt (measured in
// handleGitJob); it is recorded on mirror.sync.duration_seconds tagged with the
// disposition resolved here, so the latency sample carries the real outcome.
func (c *consumer) disposeResult(ctx context.Context, m ackableMsg, err error, provider, ulid, subject string, payload []byte, viaRekick bool, elapsed time.Duration, sourcePosition int64) {
	seq := streamSeq(m)
	switch classifyDisposition(err) {
	case dispositionAck:
		// Publish the ready completion BEFORE acking. entire-core flips
		// mirror_repos.status (processing → ready) off this event, and once we
		// ack the job leaves the work-queue stream and is never redelivered — so
		// a publish lost after the ack would strand the row in 'processing'
		// forever, hanging the CLI's status poll. publishReadyOrRetry holds the
		// ack until the publish lands (or gives up on the final delivery); see
		// its doc for the at-least-once rationale.
		if !c.publishReadyOrRetry(ctx, m, provider, ulid, elapsed, sourcePosition) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeAck, elapsed)
		_ = m.Ack()
		c.clearIndex(ctx, ulid, seq, viaRekick) // repo healed → drop any stale index entry
	case dispositionNoop:
		// Empty source: nothing to mirror, but the mirror IS clonable (an empty
		// repo is a valid clone target), so it's 'ready' to entire-core. Same
		// publish-before-ack discipline as the success path. Do NOT clear the
		// failure index here: a noop applied no refs and reconciled nothing (it
		// is deliberately not a ref-applying success — see last_success_unix), so
		// it must not prune a recorded terminal failure that may have left the
		// mirror inconsistent. Only a real sync (Ack) or a re-kick that ends in
		// one clears. A genuinely-emptied source self-heals on its next real
		// sync, or the entry ages out via the bucket ttl.
		//
		// For the same reason the completion carries NO source position: a
		// noop applied nothing, so the pre-fetch snapshot is NOT evidence the
		// placement covers that position — stamping it would over-advance the
		// applied watermark and hide the stale placement from the resync
		// sweep forever (a source whose refs were all deleted no-ops here
		// while the target still serves them). Position 0 = "no watermark
		// evidence"; the sweep stays responsible for the divergence.
		if !c.publishReadyOrRetry(ctx, m, provider, ulid, elapsed, 0) {
			return
		}
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeNoop, elapsed)
		_ = m.Ack()
	case dispositionTerm:
		// Best-effort record, then Term regardless — fail open. recordTerminal
		// logs + counts record_failed{cause} on a KV write failure; we Term
		// either way rather than Nak, because the failure is permanent (re-running
		// the sync would be wasted work) and a KV outage must not wedge the
		// consumer. Recovery of a dropped record is owned by the record_failed
		// alert + L2 reconcile, not by holding the message.
		c.recordTerminal(ctx, ulid, subject, payload, seq, failindex.ReasonPermanent, failindex.SourceWorkerPermanent, err)
		slog.WarnContext(ctx, "Permanent sync error, terminating", slog.Any("error", err))
		c.publishFailed(ctx, ulid) // best-effort: tell entire-core the clone won't land
		c.metrics.recordSyncOutcome(ctx, provider, c.jurisdiction, outcomeTerm, elapsed)
		_ = m.Term()
	case dispositionNak:
		if isLastDelivery(m) {
			// Final delivery: JetStream won't redeliver past consumerMaxDeliver,
			// so this is terminal. Best-effort record (max_deliveries), then Term —
			// fail open (recordTerminal surfaces a write failure via record_failed).
			c.recordTerminal(ctx, ulid, subject, payload, seq, failindex.ReasonMaxDeliveries, failindex.SourceWorkerExhausted, err)
