package main

import (
	"errors"
	"regexp"
	"strings"

	"connectrpc.com/connect"
	gitsync "entire.io/entire/git-sync"
)

type syncError struct {
	err       error
	permanent bool
}

func (e *syncError) Error() string { return e.err.Error() }
func (e *syncError) Unwrap() error { return e.err }

func permanentErr(err error) error { return &syncError{err: err, permanent: true} }
func transientErr(err error) error { return &syncError{err: err, permanent: false} }

// errSourceNoRefs signals that a sync did nothing because the source has no
// refs to mirror — an empty repository. It is benign, not a failure: the
// worker acks the message (so JetStream doesn't redeliver a job that can only
// ever no-op against an unchanged empty source) but records it as outcomeNoop
// so a persistently-empty source stays visible rather than masquerading as a
// healthy ref-applying sync. See disposeResult / classifyDisposition.
var errSourceNoRefs = errors.New("source has no refs to mirror")

// isNoSourceRefsError reports whether err is git-sync's "no source refs
// matched" outcome. git-sync raises this when the desired ref set is empty;
// it collapses "empty source" and "selection matched nothing" into the same
// unexported error string. The worker syncs with AllRefs and no branch
// selector or ref mappings (see syncer.go), so the only way the desired set
// comes back empty is a genuinely empty source — which is a clean no-op, not a
// failure. There is no exported sentinel to errors.Is against, so we match the
// stable message substring (consistent with permanentStatusHints below).
func isNoSourceRefsError(err error) bool {
	return err != nil && strings.Contains(err.Error(), "no source refs matched")
}

// isTransientGitFetchError reports whether err matches the intermittent
// "http 404" pattern emitted by git-sync's transport on GitHub ref-discovery
// failures. These have been observed (commit 9751992 investigation) to
// succeed on retry while the same repo and installation remain healthy.
//
// Mint-time 404s ("GitHub API returned 404: ...") are NOT classified as
// transient here — those represent a genuine installation/scope failure and
// should surface as permanent errors after the first attempt.
func isTransientGitFetchError(err error) bool {
	if err == nil {
		return false
	}
	msg := err.Error()
	if !strings.Contains(msg, "http 404") {
		return false
	}
	if strings.Contains(msg, "GitHub API returned") {
		return false
	}
	return true
}

// isConcurrentRefError reports whether err is a benign "target ref moved
// concurrently" rejection — almost always a second sync of the same repo landing
// first (rapid back-to-back webhooks, or a webhook overlapping the 15-min
// rekicker). It is a clean compare-and-swap miss, not a real failure: the next
// delivery re-plans against the new tip and applies (it usually no-ops, because
// the job that won the race already mirrored the same source state). The
// disposition layer (classifyDisposition) routes these to dispositionRaced so
// they redeliver like a nak but stay out of the sync-failure alert's nak+term
// numerator.
//
// We rely entirely on the typed gitsync.ErrTargetRefMoved sentinel; git-sync
// owns the classification. Against entire-server targets a race always surfaces
// as its compare-and-swap reason ("remote ref has changed"), which git-sync
// wraps as this sentinel — so no worker-side substring matching is needed, and
// none is done (a "non-fast-forward" rejection here would mean the source
// rewound and needs a force the worker doesn't do, NOT a race). If a non-entire
// target is ever introduced whose receive-pack phrases CAS misses differently,
// broaden git-sync's marker set rather than re-adding matching here.
//
// These are a strict subset of the transient class (classifySyncError never
// marks them permanent), so isPermanentError takes precedence in
// classifyDisposition.
func isConcurrentRefError(err error) bool {
	return errors.Is(err, gitsync.ErrTargetRefMoved)
}

// shouldMarkSpanError reports whether a sync error should surface as an error on
// the mirror.consume APM span. It mirrors the disposition layer's notion of
// "failure" so the trace error rate doesn't disagree with the outcome metric.
// Two benign cases are excluded: an empty source (errSourceNoRefs, acked as a
// no-op) and a concurrent-ref race that will redeliver and self-heal
// (dispositionRaced). A race that has EXHAUSTED redelivery (lastDelivery) is no
// longer benign — disposeResult escalates it to term — so it stays marked.
// Pure (no span/IO) so the decision is unit-testable; the handler owns the
// span side effects.
func shouldMarkSpanError(err error, lastDelivery bool) bool {
	if err == nil {
		return false
	}
	if errors.Is(err, errSourceNoRefs) {
		return false
	}
	if isConcurrentRefError(err) && !lastDelivery {
		return false
	}
	return true
}

// authHeaderPattern matches Basic/Bearer Authorization header values that can
// end up echoed in error response bodies. git-sync's transport error
// formatter (vendor .../gitproto/smarthttp.go) includes up to 64KB of the
// response body in its error string, so a malicious or buggy upstream that
// reflects the request Authorization header would leak the installation
// token (base64-encoded for Basic). github.com itself doesn't do this, but
// the cost of defence-in-depth here is tiny.
var authHeaderPattern = regexp.MustCompile(`(?i)(Basic|Bearer)\s+[A-Za-z0-9+/=_\-\.]+`)

// redactAuth replaces Authorization header values found in an error message
// with a fixed placeholder, dropping any wrap chain so the sensitive original
// cannot be recovered through errors.Unwrap.
func redactAuth(err error) error {
	if err == nil {
		return nil
	}
	redacted := authHeaderPattern.ReplaceAllString(err.Error(), "$1 <redacted>")
	if redacted == err.Error() {
		return err
	}
	return errors.New(redacted)
}

// permanentStatusHints match any response body that reveals a 4xx from either
// git-sync's transport error formatter ("http 401: ..."), the old direct-mint
// path's GitHub error formatter ("GitHub API returned 422: ..."), or
// coreapp.Minter's STS error formatter ("sts/token returned 403"). All of
// these map to "retrying will not help" — revoked install, private-repo
// without auth, repo not on the installation, wrong name, or entire-core
// refusing the mint because the mirror metadata doesn't match the request.
//
// "http 404" is permanent at this layer because the intermittent GitHub-side
// 404s are already retried in-process by sync() (see maxSyncAttempts). Any
// 404 that reaches classification has already survived those retries, so
// NATS redelivery would just repeat work.
var permanentStatusHints = []string{
	"http 401", "http 403", "http 404",
	"GitHub API returned 401",
	"GitHub API returned 403",
	"GitHub API returned 404",
	"GitHub API returned 422",
	"sts/token returned 401",
	"sts/token returned 403",
	"sts/token returned 404",
}

// permanentPushRejectHints match entire-server receive-pack rejections that no
// retry or re-fetch can clear: the push violates a hard server-side cap, so the
// same source state is rejected identically on every delivery and every re-kick.
// The repo only becomes syncable again if the source shrinks back under the cap
// or the server limit is raised — neither of which a redelivery can effect — so
// these must Term on the first attempt rather than burning all 10 deliveries
// into a max_deliveries record that the re-kicker then re-drives forever.
//
// Unlike permanentStatusHints these do not reliably ride on an HTTP status, so a
// status-code hint would miss them; we match the stable rejection phrase (the
// counts and byte limits vary):
//
//   - "too many ref-update commands: N (limit M)" — entire-server caps the
//     ref-update batch on the bootstrap receive-pack POST; surfaces as http 400.
//   - "body exceeded size limit B" — the pack exceeds the receive-pack body cap;
//     surfaces only in the report-status ("unpack error: push rejected: ...")
//     with no HTTP status attached.
var permanentPushRejectHints = []string{
	"too many ref-update commands",
	"body exceeded size limit",
}

// classifySyncError maps an error to a permanent or transient syncError. An
// error is permanent when its message reveals either a 4xx that retrying cannot
// fix (permanentStatusHints) or a hard receive-pack cap that the same source
// state will always trip (permanentPushRejectHints); everything else is treated
// as transient and redelivered.
func classifySyncError(err error) error {
	msg := err.Error()
	for _, hint := range permanentStatusHints {
		if strings.Contains(msg, hint) {
			return permanentErr(err)
		}
	}
	for _, hint := range permanentPushRejectHints {
		if strings.Contains(msg, hint) {
			return permanentErr(err)
		}
	}
	return transientErr(err)
}

// classifyRecoveryError classifies a default-branch reconcile failure,
// preserving auth redaction. Three shapes are distinguished:
//
//   - An already-classified *syncError (e.g. the non-convergent excluded-HEAD
//     case, marked permanent by recoverDefaultBranchRename) is respected as-is
//     so that judgment isn't re-flattened by the message-hint classifier.
//   - A connect.Error from RepoAdmin.SetDefaultBranch is classified by code
//     against an explicit PERMANENT allowlist (InvalidArgument /
//     PermissionDenied / NotFound — states redelivery provably can't fix);
//     every other code redelivers. See recoveryIsPermanent for why the
//     default is transient (mixed-version rollouts, DB blips, shutdown).
//   - Anything else (a probe or re-run replicate error) falls back to the
//     standard git-fetch/push classifier.
//
// The permanence is decided on the raw error (so the connect type survives),
// then the returned syncError carries the redacted message.
func classifyRecoveryError(err error) error {
	permanent := recoveryIsPermanent(err)
	redacted := redactAuth(err)
	if permanent {
		return permanentErr(redacted)
	}
	return transientErr(redacted)
}

func recoveryIsPermanent(err error) bool {
	var se *syncError
	if errors.As(err, &se) {
		return se.permanent
	}
	var ce *connect.Error
	if errors.As(err, &ce) {
		// Permanent is an EXPLICIT allowlist — only codes that provably
		// cannot heal through redelivery: InvalidArgument (the handler
		// rejected the target, e.g. unmirrored namespace — same state every
		// retry), PermissionDenied (the handler denied this caller on this
		// repo), NotFound (repo torn down). Everything else redelivers.
		// This deliberately includes shapes that are NOT the RPC's fault:
		// Unauthenticated/Unimplemented are what an old entiredb node
		// returns during a mixed-version rollout (HTTP 401/404 — see
		// connect's httpToCode); Internal/Unknown cover a server-side DB
		// blip or an LB error page; Canceled/DeadlineExceeded cover a
		// SIGTERM or budget cutoff racing the RPC. Terming any of those
		// would permanently wedge a recoverable mirror (the rekicker skips
		// reason=permanent), whereas transient misclassification of a true
		// misconfig only costs bounded redelivery churn that is visible on
		// the recovery-error span label and heals as soon as the config or
		// rollout does.
		switch ce.Code() {
		case connect.CodeInvalidArgument,
			connect.CodePermissionDenied,
			connect.CodeNotFound:
			return true
		default:
			return false
		}
	}
	return isPermanentError(classifySyncError(err))
}

// recoveryErrorCode returns a low-cardinality label for the reconcile failure
// — the connect code for an RPC error, else a coarse bucket — for the
// entire.sync.default_branch_recovery_error span attribute, so an operator can
// tell "SetDefaultBranch is misconfigured fleet-wide" (permission_denied /
// unimplemented) from "GitHub is flaky" (fetch) without reading every span's
// message.
func recoveryErrorCode(err error) string {
	// Unusable-source-HEAD shapes first: neither is a fetch problem, and
	// the fallthrough label would misdirect triage toward GitHub.
	switch {
	case errors.Is(err, errSourceHEADNotBranch):
		return "non_branch_head"
	case errors.Is(err, errSourceHEADMidRename):
		return "mid_rename"
	}
	var se *syncError
	if errors.As(err, &se) && se.permanent {
		if !isConnectErr(err) {
			return "non_convergent"
		}
	}
	var ce *connect.Error
	if errors.As(err, &ce) {
		return ce.Code().String()
	}
	return "fetch"
}

func isConnectErr(err error) bool {
	var ce *connect.Error
	return errors.As(err, &ce)
}

