package refstore

import (
	"context"
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"log/slog"
	"strconv"
	"strings"
	"time"

	"entire.io/internal/pgutil"
	"entire.io/repositories"
	"entire.io/slogutil"
	"github.com/jackc/pgx/v5"
)

// Per-repo write positions back the native-mirror resync sweep
// (ADR 20260818-native-mirror-resync-sweep, COR-1283): a single-writer
// logical counter bumped in the same transaction as the ref write, so "the
// primary is at position N" can never run ahead of or behind the refs it
// describes. Consumers compare ordinals; a repo with no row is at position 0.
//
// Monotonicity is the ONLY invariant consumers may rely on — not density.
// The layered write paths bump per successful mutation (a batch bumps once),
// and the one-shot push path bumps unconditionally per push (its pipelined
// batch cannot gate the bump on the CAS outcomes without a mid-transaction
// round trip), so ordinals advance at least once per committed
// write-transaction and occasionally more.

// RepoWritePosition is one repo's write position row: the monotonic ordinal
// plus the scan-cursor timestamp of its last advance. UpdatedAt is a cursor,
// never an ordering primitive — staleness comparisons are ordinal vs ordinal.
type RepoWritePosition struct {
	RepoID    repositories.ID
	Ordinal   int64
	UpdatedAt time.Time
}

// derivePositionsTableName maps a per-test refs table name to its positions
// sibling. The readable "<refs>_wpos" form is used when it fits; otherwise a
// deterministic hash form, because PostgreSQL silently TRUNCATES identifiers
// over 63 bytes rather than erroring, and a truncated name could collide
// across tests instead of failing loudly. Production never takes this path —
// NewPostgresStoreFromPool pins "repo_write_positions" (migration 023).
func derivePositionsTableName(tableName string) string {
	derived := tableName + "_wpos"
	if validTableName.MatchString(derived) {
		return derived
	}
	sum := sha256.Sum256([]byte(tableName))
	return "wpos_" + hex.EncodeToString(sum[:8])
}

// bumpWritePositionSQL returns the single upsert statement that advances
// repoID's write position. Shared by the per-method bumps below and the
// one-shot push batch (oneshot.go), so the two write paths cannot drift.
//
// updated_at is stamped with clock_timestamp() — statement-execution time —
// deliberately NOT the transaction-start NOW() refs.updated_at uses: the
// delta scan's grace window (writePositionsCursorGrace) must cover the gap
// between the stamp and the commit, and with NOW() that gap is the WHOLE
// transaction duration — a push that waits longer than the grace on the
// per-repo D/F advisory lock would commit a position already invisible to
// every delta pass, downgrading its staleness bound to the full-rescan
// interval. The bump executes after the CAS statements on both write paths,
// so with clock_timestamp() the gap is only the tail of the transaction
// (bump-to-commit), comfortably inside the grace.
func (s *PostgresStore) bumpWritePositionSQL(repoID repositories.ID) (string, []any) {
	return fmt.Sprintf(`
		INSERT INTO %s (repo_id, ordinal, updated_at) VALUES ($1, 1, clock_timestamp())
		ON CONFLICT (repo_id) DO UPDATE SET ordinal = %s.ordinal + 1, updated_at = clock_timestamp()`,
		s.positionsTableName, s.positionsTableName), []any{repoID.String()}
}

// bumpWritePosition advances repoID's write position on the ambient
// transaction (or the pool when none). Inside a transaction a failure is
// returned so the caller rolls the ref write back — a committed write whose
// position didn't advance is invisible to the resync sweep, the silent loss
// the watermark exists to prevent (same fail-closed rule as the ref-event
// outbox). Outside a transaction the ref write has already committed, so
// failing the call would misreport a durable write; the error is returned for
// the caller to log-and-continue.
func (s *PostgresStore) bumpWritePosition(ctx context.Context, repoID repositories.ID) error {
	sql, args := s.bumpWritePositionSQL(repoID)
	if _, err := s.db(ctx).Exec(ctx, sql, args...); err != nil {
		return fmt.Errorf("bump write position: %w", err)
	}
	return nil
}

// writePositionsCursorGrace is subtracted from the caller's cursor before the
// delta scan, for the same reason as dirtyReposCursorGrace: updated_at is
// stamped before the commit (clock_timestamp() at bump execution, see
// bumpWritePositionSQL), so a position stamped before a cursor read but
// committed after it would otherwise be invisible to every subsequent sweep.
// The stamp-to-commit gap is only the transaction's tail, so a minute of
// grace is generous. Over-scanning is cheap (a re-surfaced position compares
// equal and no-ops); under-scanning silently hides a stale placement from
// the sweep.
const writePositionsCursorGrace = time.Minute

// WritePositionsMaxPageSize bounds one WritePositionsSince page. Without a
// bound, the first-ever scan (and every full rescan) would materialize the
// whole position table into one response — and a response too big to marshal
// fails the same way every retry, wedging the caller's delta lane
// permanently. One page of 10k rows is ~a few hundred KB on the wire.
const WritePositionsMaxPageSize = 10_000

// ErrInvalidPageToken is returned when a continuation token is not one this
// server issued. Callers must restart the walk with an empty token rather
// than fall back to a fresh scan silently: querying on a garbage keyset would
// return a window nobody asked for, and the caller would persist a cursor
// past rows it never read.
var ErrInvalidPageToken = errors.New("invalid write-positions page token")

// writePositionsToken is the opaque continuation state for one walk: the
// walk's fixed upper bound plus the keyset position it has reached.
//
// The bound and the keyset travel TOGETHER on purpose. If a caller could
// supply them as separate fields it could pair this walk's keyset with
// another walk's bound; a bound older than the keyset truncates the scan
// early while the caller still persists the newer walk-start as its cursor,
// so every row in between is never read by any pass. One token makes that
// pairing unrepresentable.
//
// Opaque but unsigned, matching the house cursor convention (core/pagination
// documents the same trade-off): it carries only ordering bounds, never
// scope. Authorization is re-derived per request, so forging a token can at
// most reposition the caller inside the fleet-wide window it is already
// authorized to read.
//
// Timestamps are encoded as microseconds since the Unix epoch because that is
// exactly PostgreSQL's TIMESTAMPTZ resolution: a value read out of
// updated_at round-trips through the token bit-for-bit, so the keyset
// predicate can neither skip a row nor re-read one through a precision
// mismatch.
type writePositionsToken struct {
	// bound is the walk's exclusive-upper-bound clock, fixed at page one.
	bound time.Time
	// afterTime, afterRepo is the (updated_at, repo_id) keyset of the last row
	// the previous page returned.
	afterTime time.Time
	afterRepo string
}

func encodeWritePositionsToken(t writePositionsToken) string {
	return base64.RawURLEncoding.EncodeToString([]byte(strings.Join([]string{
		strconv.FormatInt(t.bound.UnixMicro(), 10),
		strconv.FormatInt(t.afterTime.UnixMicro(), 10),
		t.afterRepo,
	}, "\x00")))
}

func decodeWritePositionsToken(token string) (writePositionsToken, error) {
	raw, err := base64.RawURLEncoding.DecodeString(token)
	if err != nil {
		return writePositionsToken{}, fmt.Errorf("decode page token: %w", ErrInvalidPageToken)
	}
	parts := strings.Split(string(raw), "\x00")
	if len(parts) != 3 {
		return writePositionsToken{}, fmt.Errorf("page token has %d parts, want 3: %w", len(parts), ErrInvalidPageToken)
	}
	bound, err := strconv.ParseInt(parts[0], 10, 64)
	if err != nil {
		return writePositionsToken{}, fmt.Errorf("page token bound %q: %w", parts[0], ErrInvalidPageToken)
	}
	after, err := strconv.ParseInt(parts[1], 10, 64)
	if err != nil {
		return writePositionsToken{}, fmt.Errorf("page token keyset time %q: %w", parts[1], ErrInvalidPageToken)
	}
	// Validated rather than passed through: the query parameterizes it, so a
	// bad value is not an injection risk, but it would silently reposition the
	// walk. Fail loudly instead.
	var repoID repositories.ID
	if err := repoID.UnmarshalText(parts[2]); err != nil {
		return writePositionsToken{}, fmt.Errorf("page token repo id %q: %w", parts[2], ErrInvalidPageToken)
	}
	return writePositionsToken{
		bound:     time.UnixMicro(bound).UTC(),
		afterTime: time.UnixMicro(after).UTC(),
		afterRepo: repoID.String(),
	}, nil
}

// WritePositionsPage is one page of the resync sweep's per-cluster delta read.
type WritePositionsPage struct {
	// Positions advanced inside this walk's window, ordered by
	// (updated_at, repo_id).
	Positions []RepoWritePosition

	// WalkStart is the database clock read at the START of this walk, and it
	// is IDENTICAL on every page of the walk. It serves both roles at once:
	// the walk's inclusive upper bound, and the value the caller persists as
	// the next pass's `since`. Because it does not vary per page, there is no
	// wrong page to read it from.
	WalkStart time.Time

	// NextPageToken continues THIS walk. Empty means the walk is complete.
	NextPageToken string
}

// WritePositionsSince returns one page of repo write positions that advanced
// after the caller's cursor — the resync sweep's per-cluster delta read.
// Write-proportional by construction: idle repos never appear.
//
// The walk is a BOUNDED scan, not an open-ended tail. Page one reads the
// database clock and fixes it as the walk's upper bound; every continuation
// carries that same bound in its token and applies `updated_at <= bound`.
// Without the upper bound the scan has only a lower bound on a MUTABLE sort
// key, so a repo returned on an earlier page that is written again moves
// ahead of the keyset and is returned a second time in the same walk — and
// while writes keep refilling the page from below, "page not full" (the
// termination condition) can keep not happening. The bound makes the walk's
// page count a function of the table, which is what lets the ADR quote a
// per-pass cost at all.
//
// Paging protocol. The FIRST call of a pass passes an empty pageToken and
// scans `since - grace < updated_at <= bound` (the grace re-scan covers
// stamp-to-commit skew across passes, see writePositionsCursorGrace). A
// truncated page returns a NextPageToken; the CONTINUATION call passes it
// back verbatim and resumes on an EXACT keyset predicate — no grace, because
// re-applying it intra-pass could re-read the same page forever whenever one
// grace-window of writes exceeds a page. An empty NextPageToken means the
// walk is complete. Rows are ordered (updated_at, repo_id), served by
// repo_write_positions_updated_at_idx, and the bound is a prefix of that same
// index so it costs nothing to apply.
//
// The caller persists WalkStart as the next pass's `since`. Anchoring the
// cross-pass cursor at the walk's END instead would leave a hole: a row whose
// stamp a page boundary already passed but whose transaction commits mid-walk
// is missed by this walk, and a walk longer than the grace window puts that
// stamp beyond the next pass's grace re-scan too — silently degrading the
// repo's staleness bound to the full-rescan interval. Anchored at walk start,
// consecutive passes tile the timeline edge to edge with a grace-width
// overlap, so a row rewritten mid-walk (now excluded by this walk's bound) is
// inside the next pass's window by construction, independent of how long
// either walk ran.
func (s *PostgresStore) WritePositionsSince(ctx context.Context, since time.Time, pageToken string, limit int) (WritePositionsPage, error) {
	db := s.db(ctx)
	if limit <= 0 || limit > WritePositionsMaxPageSize {
		limit = WritePositionsMaxPageSize
	}

	var (
		bound time.Time
		rows  pgx.Rows
		err   error
	)
	if pageToken == "" {
		if err := db.QueryRow(ctx, "SELECT now()").Scan(&bound); err != nil {
			return WritePositionsPage{}, fmt.Errorf("read db clock: %w", err)
		}
		// Normalized to UTC because the same instant reaches the caller two
		// ways — scanned from the driver here on page one, rebuilt from the
		// token's epoch microseconds on every continuation — and a
		// location-carrying time.Time compares unequal to its own UTC twin
		// under reflect.DeepEqual even when both name the same instant. A
		// consumer that checks "did the bound drift across pages?" would see a
		// phantom drift. Normalizing at the one place the driver's location
		// enters keeps WalkStart byte-identical across a walk.
		bound = bound.UTC()
		rows, err = db.Query(ctx, fmt.Sprintf(
			`SELECT repo_id, ordinal, updated_at FROM %s
			 WHERE updated_at > $1 AND updated_at <= $2
			 ORDER BY updated_at, repo_id LIMIT $3`, s.positionsTableName),
			since.Add(-writePositionsCursorGrace), bound, limit)
	} else {
		tok, tokErr := decodeWritePositionsToken(pageToken)
		if tokErr != nil {
			return WritePositionsPage{}, tokErr
		}
		// No clock read on a continuation: the bound is already fixed in the
		// token, so a continuation page costs one query instead of two.
		bound = tok.bound
		rows, err = db.Query(ctx, fmt.Sprintf(
			`SELECT repo_id, ordinal, updated_at FROM %s
			 WHERE (updated_at, repo_id) > ($1, $2) AND updated_at <= $3
			 ORDER BY updated_at, repo_id LIMIT $4`, s.positionsTableName),
			tok.afterTime, tok.afterRepo, bound, limit)
	}
	if err != nil {
		return WritePositionsPage{}, fmt.Errorf("query write positions since: %w", err)
	}
	defer rows.Close()

	var out []RepoWritePosition
	for rows.Next() {
		var idStr string
		var p RepoWritePosition
		if err := rows.Scan(&idStr, &p.Ordinal, &p.UpdatedAt); err != nil {
			return WritePositionsPage{}, fmt.Errorf("scan write position: %w", err)
		}
		if err := p.RepoID.UnmarshalText(idStr); err != nil {
			return WritePositionsPage{}, fmt.Errorf("parse repo id %q: %w", idStr, err)
		}
		// UTC for the same reason as bound above: UpdatedAt goes out to the
		// caller AND into the next page's token, and the token rebuilds it from
		// epoch microseconds. One location for both.
		p.UpdatedAt = p.UpdatedAt.UTC()
		out = append(out, p)
	}
	if err := rows.Err(); err != nil {
		return WritePositionsPage{}, fmt.Errorf("iterate write positions: %w", err)
	}

	page := WritePositionsPage{Positions: out, WalkStart: bound}
	if len(out) == limit {
		last := out[len(out)-1]
		page.NextPageToken = encodeWritePositionsToken(writePositionsToken{
			bound:     bound,
			afterTime: last.UpdatedAt,
			afterRepo: last.RepoID.String(),
		})
	}
	return page, nil
}

// WritePosition returns repoID's current write-position ordinal, 0 when the
// repo has taken no write since the position table landed — "position 0" is
// the defined pre-watermark state, not an error. The mirror worker snapshots
// this immediately before fetching so a completed sync can report the
// position it provably covers.
func (s *PostgresStore) WritePosition(ctx context.Context, repoID repositories.ID) (int64, error) {
	var ordinal int64
	err := s.db(ctx).QueryRow(ctx, fmt.Sprintf(
		`SELECT ordinal FROM %s WHERE repo_id = $1`, s.positionsTableName),
		repoID.String()).Scan(&ordinal)
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, nil
	}
	if err != nil {
		return 0, fmt.Errorf("query write position: %w", err)
	}
	return ordinal, nil
}

// logWritePositionMiss records a swallowed out-of-transaction bump failure:
// the ref write committed but the position didn't advance, so the resync
// sweep cannot see this write until the repo's next one. Warn, not error —
// the miss self-heals and the write itself succeeded.
func logWritePositionMiss(ctx context.Context, repoID repositories.ID, err error) {
	slogutil.Warn(ctx, "refstore: write-position bump failed outside a transaction; staleness of this write is invisible to the resync sweep until the next write",
		slog.String("repo_id", repoID.String()),
		slog.Any("error", err),
	)
}

// bumpOrLogOutsideTx applies the bump's two-mode error contract (see
// bumpWritePosition): inside a transaction the error propagates so the write
// rolls back with it; outside, the ref write is already durable, so the miss
// is logged and swallowed — the position self-heals on the repo's next write.
func (s *PostgresStore) bumpOrLogOutsideTx(ctx context.Context, repoID repositories.ID) error {
	err := s.bumpWritePosition(ctx, repoID)
	if err == nil {
		return nil
	}
	if pgutil.TxFromContext(ctx) != nil {
		return err
	}
	logWritePositionMiss(ctx, repoID, err)
	return nil
}

