	FullScanInterval time.Duration
	// MaxRepairsPerPass caps repair publishes in one pass, so a post-outage
	// backlog drains as a trickle across passes, not a stampede.
	MaxRepairsPerPass int
	// RepairInterval spaces consecutive repair publishes within a pass.
	RepairInterval time.Duration
	// DryRun walks both phases against production data but suppresses the
	// flag writes and the repair publishes, logging what a real pass would do.
	DryRun bool
}

func (c ResyncSweepConfig) withDefaults() ResyncSweepConfig {
	if c.Grace == 0 {
		c.Grace = 5 * time.Minute
	}
	if c.RepublishBackoff == 0 {
		c.RepublishBackoff = 30 * time.Minute
	}
	if c.FullScanInterval == 0 {
		c.FullScanInterval = 24 * time.Hour
	}
	if c.MaxRepairsPerPass == 0 {
		c.MaxRepairsPerPass = 200
	}
	if c.RepairInterval == 0 {
		c.RepairInterval = 200 * time.Millisecond
	}
	return c
}

// ResyncSweep is one-pass state; construct per run (the run-once CronJob
// shape, singleton semantics from Kubernetes).
type ResyncSweep struct {
	pool      *pgxpool.Pool
	positions SweepPositionLister
	publisher SweepRepairPublisher
	clusters  []SweepCluster
	cfg       ResyncSweepConfig
}

func NewResyncSweep(pool *pgxpool.Pool, positions SweepPositionLister, publisher SweepRepairPublisher, clusters []SweepCluster, cfg ResyncSweepConfig) *ResyncSweep {
	return &ResyncSweep{pool: pool, positions: positions, publisher: publisher, clusters: clusters, cfg: cfg.withDefaults()}
}

// ResyncSweepResult is one pass's outcome, for logs, metrics, and the
// run-once exit code. Clean is false when any per-cluster or per-placement
// step failed — the pass still processes everything it can (a failed home
// cluster must not stop the repair phase), and the CronJob exits non-zero so
// the failure lands as kube_job_failed.
type ResyncSweepResult struct {
	Clean bool
	// Clear phase (flags dropped against the PREVIOUS pass's targets).
	Healed            int
	NotServingCleared int
	// Detect phase.
	ClustersSwept int
	// ClustersUnsweepable counts this jurisdiction's clusters with no
	// internal URL — primaries homed there are invisible to detection.
	ClustersUnsweepable int
	ClusterFailures     int
	PositionsScanned    int
	// PagesRead counts position pages this pass pulled across all clusters.
	// The walk's page count is a function of the position table (that is what
	// the server-side bound buys), so this is the number that tells an
	// operator a pass is growing pages rather than growing rows — and the one
	// that would show a walk failing to converge before the pass timed out.
	PagesRead int
	Flagged   int
	// CursorNotAdvanced counts clusters whose delta was READ AND APPLIED but
	// whose cursor could not be checkpointed — either the serving cluster
	// returned no walk start, or the save failed. Distinct from
	// ClusterFailures, which also counts clusters whose delta could not be
	// read at all: here the flags are correct and only the bookmark is
	// missing, so the next pass re-reads a window that grows every time. Both
	// still fail the cluster; this is what tells an operator WHICH story it is.
	CursorNotAdvanced int
	// WalkRestarts counts walks restarted from an empty page token because
	// the serving cluster rejected a continuation token. Self-healing, so not
	// a pass failure, but it doubles that cluster's scan for the pass — a
	// standing non-zero means tokens are being invalidated every pass.
	WalkRestarts int
	// Repair phase (this jurisdiction's standing flags).
	RepairsPublished int
	PublishFailures  int
	SkippedNoSource  int
	SkippedByCap     int
	// SkippedHealed counts repairs not published because the placement caught
	// up (or lost its flag) between the behind set being selected and its turn
	// in the paced loop. Steady non-zero is healthy — the event path winning a
	// race the sweep is only the backstop for — but a large share means the
	// grace window is shorter than the done stream's real settling time.
	SkippedHealed       int
	Behind              int
	OldestBehindSeconds float64
	// Global sample (every jurisdiction's standing flags): how another
	// jurisdiction's stopped or undeployed sweep becomes visible from this
	// one.
	GlobalBehind              int
	GlobalOldestBehindSeconds float64
}

// Run executes one pass: clear flags proven healed or moot, detect over this
// jurisdiction's home clusters, repair this jurisdiction's remaining flagged
// placements, then sample the global staleness gauges. Phase errors are
// accumulated, never short-circuiting the later phases.
//
// The CLEAR phase deliberately runs BEFORE detect, comparing each flag's
// applied watermark against the target the flag held at the END of the
// previous pass — i.e. a target at least one cadence old. A continuously
// written, healthily replicating repo has an applied watermark that trails
// its primary by at most the done-stream's duplicate window, so against a
// cadence-old target it compares caught-up and the flag clears (detect then
// re-flags with a FRESH resync_due_at). Clearing after detect would compare
// against the target detect just raised, which such a repo never satisfies —
// the flag would stand forever with a frozen due_at, growing the staleness
// age (and the RPO alarm) without bound for a placement that is seconds
// behind. A genuinely stale placement never clears either way, so its due_at
// stays honestly frozen at first detection.
func (s *ResyncSweep) Run(ctx context.Context) (ResyncSweepResult, error) {

func (s *ResyncSweep) detectCluster(ctx context.Context, c SweepCluster, res *ResyncSweepResult) error {
	since, fullScanAt, err := s.loadCursor(ctx, c.Slug)
	if err != nil {
		return err
	}
	fullScan := time.Since(fullScanAt) >= s.cfg.FullScanInterval
	if fullScan {
		since = time.Time{}
	}

	pageToken := ""
	restarted := false
	var walkStart time.Time
	// No page cap, deliberately. The server-side bound makes the page count a
	// function of the position table inside the window, so the loop is finite
	// by construction, and ctx already exits it (cancellation surfaces as a
	// failed RPC). A cap that advanced the cursor would silently drop unread
	// rows — a coverage hole worse than the pathology it guards — and a cap
	// that failed instead would have to be set so high it only ever catches a
	// server bug. The wall-clock bound belongs on the CronJob
	// (activeDeadlineSeconds), where one setting covers a runaway walk, a slow
	// cluster and a hung RPC alike. PagesRead is the early diagnostic.
	for {
		page, err := s.positions.ListWritePositions(ctx, c.InternalURL, since, pageToken)
		if err != nil {
			// A continuation token the serving cluster no longer recognizes
			// (a rolled data plane, a changed token encoding): restart the
			// walk from an empty token ONCE. Retrying the rejected token
			// would fail this cluster every pass forever, and failing outright
			// would wedge its detection on a value the sweep itself is
			// holding, while a restart only re-reads a delta the flagging is
			// idempotent over. Exactly once, because a SECOND rejection is of
			// a token this same walk just issued — the server is broken, not
			// the token stale — and looping on it would never terminate.
			if errors.Is(err, ErrInvalidPageToken) && pageToken != "" && !restarted {
				restarted = true
				pageToken = ""
				res.WalkRestarts++
				slogutil.Warn(ctx, "resync sweep: cluster rejected the continuation token; restarting the walk once from an empty token",
					slog.String("cluster", c.Slug), slog.Any("error", err))
				continue
			}
			return fmt.Errorf("list write positions: %w", err)
		}
		// Identical on every page by contract, so a plain assignment is the
		// whole bookkeeping — and after a restart it holds the RESTARTED
		// walk's bound, the only walk whose window was read end to end.
		walkStart = page.WalkStart
		// Counts rows this pass actually read, so a restart's re-read shows up
		// as the extra scan it was. Flagged does not double-count it: the
		// update's target-ordinal guard makes a re-flag affect no rows.
		res.PagesRead++
		res.PositionsScanned += len(page.Positions)

		const chunk = 500
		for start := 0; start < len(page.Positions); start += chunk {
			end := min(start+chunk, len(page.Positions))
			flagged, err := s.flagBehind(ctx, page.Positions[start:end])
			if err != nil {
				return fmt.Errorf("flag behind placements: %w", err)
			}
			res.Flagged += flagged
		}

		if page.NextPageToken == "" {
			break
		}
		pageToken = page.NextPageToken
	}

	if walkStart.IsZero() {
		// Never persist a zero cursor. It would silently demote this cluster
		// to a full rescan on every pass while the pass still reported clean.
		// walk_start is a clock read the serving cluster always stamps, so a
		// zero here is a protocol break: fail this one cluster loudly (the
		// pass goes unclean, its cursor stays put) and let the rest sweep.
		res.CursorNotAdvanced++
		slogutil.Error(ctx, "resync sweep: cluster returned no walk start; its delta WAS applied but the cursor cannot be checkpointed",
			slog.String("cluster", c.Slug))
		return fmt.Errorf("cluster %s returned no walk start", c.Slug)
	}

	if s.cfg.DryRun {
		return nil // don't advance the cursor either: a real pass must re-see this delta
	}
	if err := s.saveCursor(ctx, c.Slug, walkStart, fullScan); err != nil {
		// Same operator story as the zero walk start above, different cause:
		// the flags this pass raised are correct and durable, and only the
		// bookmark is missing — so say that, rather than leaving it to read
		// like a cluster the sweep could not talk to.
		res.CursorNotAdvanced++
		slogutil.Error(ctx, "resync sweep: cursor save failed; this cluster's delta WAS applied but will be re-read next pass",
			slog.String("cluster", c.Slug), slog.Any("error", err))
		return err
	}
	return nil
}

// flagBehind stamps the behind-flag on every serving placement of the given
// primaries whose applied watermark trails the primary's ordinal.
// resync_due_at keeps its FIRST value (staleness age); resync_target_ordinal
// rises monotonically. In dry-run it only counts what would be flagged.
func (s *ResyncSweep) flagBehind(ctx context.Context, positions []SweepRepoPosition) (int, error) {
	if len(positions) == 0 {
		return 0, nil
	}
	values := make([]string, 0, len(positions))
	args := make([]any, 0, 2*len(positions))
	for i, p := range positions {
		// Explicit casts: CockroachDB cannot infer a bare VALUES placeholder's
		// type (42P18).
		values = append(values, fmt.Sprintf("($%d::STRING, $%d::INT8)", 2*i+1, 2*i+2))
		args = append(args, p.RepoID, p.Ordinal)
	}
	valuesClause := "(VALUES " + strings.Join(values, ", ") + ") AS v(repo_id, ordinal)"

	if s.cfg.DryRun {
		var n int
		err := s.pool.QueryRow(ctx,
			`SELECT count(*) FROM `+valuesClause+`
			 JOIN repo_group g ON g.forge = 'entire' AND g.forge_repo_id = v.repo_id
			 JOIN native_mirrors nm ON nm.repo_group_id = g.id
			 WHERE nm.applied_position < v.ordinal
			   AND nm.stage IN `+servingStages+`
			   AND nm.desired_state = 'active' AND nm.suspended_at IS NULL
			   AND nm.creation_failed_at IS NULL
			   AND (nm.resync_due_at IS NULL OR nm.resync_target_ordinal < v.ordinal)`,
			args...).Scan(&n)
		if err != nil {
			return 0, fmt.Errorf("dry-run count: %w", err)
		}
		return n, nil
	}

	tag, err := s.pool.Exec(ctx,
		`UPDATE native_mirrors AS nm
		 SET resync_due_at = COALESCE(nm.resync_due_at, now()),
		     resync_target_ordinal = GREATEST(nm.resync_target_ordinal, v.ordinal)
		 FROM `+valuesClause+`
		 JOIN repo_group g ON g.forge = 'entire' AND g.forge_repo_id = v.repo_id
		 WHERE nm.repo_group_id = g.id
		   AND nm.applied_position < v.ordinal
		   AND nm.stage IN `+servingStages+`
		   AND nm.desired_state = 'active' AND nm.suspended_at IS NULL
		   AND nm.creation_failed_at IS NULL
		   AND (nm.resync_due_at IS NULL OR nm.resync_target_ordinal < v.ordinal)`,
		args...)
	if err != nil {
		return 0, fmt.Errorf("flag update: %w", err)
	}
	return int(tag.RowsAffected()), nil
}

