// updateHEADIfTargetMissing keeps the repository default branch usable after
// the first successful push to a non-main branch. Provisioning seeds HEAD to
// refs/heads/main. If the first push creates a different branch, leaving HEAD
// pointed at main makes clones warn that remote HEAD is nonexistent and skip
// checkout.
func updateHEADIfTargetMissing(st *storage.Storage, commands []*packp.Command, cmdErrors map[plumbing.ReferenceName]error) error {
	target, ok := firstSuccessfulBranchUpdate(commands, cmdErrors)
	if !ok {
		return nil
	}

	head, err := st.Reference(plumbing.HEAD)
	switch {
	case errors.Is(err, plumbing.ErrReferenceNotFound):
		if err := st.SetReference(plumbing.NewSymbolicReference(plumbing.HEAD, target)); err != nil {
			return fmt.Errorf("set HEAD: %w", err)
		}
		return nil
	case err != nil:
		return fmt.Errorf("read HEAD: %w", err)
	case head.Type() != plumbing.SymbolicReference:
		return nil
	}

	if _, err := st.Reference(head.Target()); err == nil {
		return nil
	} else if !errors.Is(err, plumbing.ErrReferenceNotFound) {
		return fmt.Errorf("resolve HEAD target %s: %w", head.Target(), err)
	}

	if err := st.SetReference(plumbing.NewSymbolicReference(plumbing.HEAD, target)); err != nil {
		return fmt.Errorf("set HEAD: %w", err)
	}
	return nil
}

func firstSuccessfulBranchUpdate(commands []*packp.Command, cmdErrors map[plumbing.ReferenceName]error) (plumbing.ReferenceName, bool) {
	for _, cmd := range commands {
		if err := cmdErrors[cmd.Name]; err != nil {
			continue
		}
		if !cmd.Name.IsBranch() || gitwire.CommandAction(cmd) == packp.Delete {
			continue
		}
		return cmd.Name, true
	}
	return "", false
}

