const DenyCurrentBranchDeletionReason = "deletion of the current branch prohibited"

// denyCurrentBranchDelete returns per-ref errors for delete commands whose
// target is the branch HEAD currently points at, matching upstream git's
// receive.denyCurrentBranch=refuse (delete-only) policy. Returns nil if HEAD
// is missing, detached, or no command targets the current branch.
func denyCurrentBranchDelete(st *storage.Storage, cmds []*packp.Command) map[plumbing.ReferenceName]error {
	current, ok := currentBranch(st)
	if !ok {
		return nil
	}
	var out map[plumbing.ReferenceName]error
	for _, cmd := range cmds {
		if gitwire.CommandAction(cmd) != packp.Delete {
			continue
		}
		if cmd.Name != current {
			continue
		}
		if out == nil {
			out = make(map[plumbing.ReferenceName]error)
		}
		out[cmd.Name] = errors.New(DenyCurrentBranchDeletionReason)
	}
	return out
}

