//
// The repo's hash algorithm is folded into the advertisement as the
// `object-format=<algo>` capability whenever it is not the protocol
// default (sha1). Without it, real git clients refuse SHA256 fetches
// with "the receiving end does not support this repository's hash
// algorithm" — same bug we fixed for the v0/v1 receive-pack side in
// info_refs.go's advertiseRefs.
func (s *Service) serveV2InfoRefs(w http.ResponseWriter, r *http.Request, st *storage.Storage) bool {
	if s.V2Registry == nil {
		return false
	}
	if v2dispatch.ProtocolVersionFromHeader(r.Header.Get("Git-Protocol")) != v2dispatch.V2 {
		return false
	}
	// Protocol v2 only defines fetch-side commands (ls-refs, fetch,
	// bundle-uri); there is no v2 push. Returning a v2 capability
	// advertisement on a receive-pack info/refs misleads JGit-based and
	// other v2-experimental push clients into POSTing a v2-framed body
	// to /git-receive-pack — the v0/v1 decoder then rejects it with
	// "capabilities delimiter not found" → 400. Fall through to the
	// v0/v1 HandleInfoRefs which advertises receive-pack capabilities
	// the client can actually push against.
	if r.URL.Query().Get("service") == transport.ReceivePackService {
		return false
	}
	_, span := otel.Tracer().Start(r.Context(), "githttp.serveV2InfoRefs")
	defer span.End()
	w.Header().Set("Content-Type", "application/x-git-upload-pack-advertisement")
	w.Header().Set("Cache-Control", "no-cache")
	var extras []string
	if st != nil {
		// v2 always emits object-format on info/refs — sha1 and
		// sha256 alike (serve.c:53-58, object_format_advertise
		// returns 1 unconditionally and writes r->hash_algo->name
		// into the capability value).
		extras = append(extras, "object-format="+objectformat.Advertise(st.ObjectFormat()))
	}
	// The entire remote helper (git-remote-entire) proxies fetches to a
	// replica node; drop ref-in-want from its advertisement so native git,
	// driving through it, negotiates with explicit want <oid> lines instead
	// of a server-side ref resolution that could race this advertisement.
	opts := v2dispatch.CapabilityOptions{
		RemoteHelper: gitspan.ClassifyClientUA(r.Header.Get("User-Agent")) == gitspan.ClientKindEntireHelper,
	}
	if err := v2dispatch.AdvertiseCapabilities(w, version.GitAgent(), s.V2Registry, opts, extras...); err != nil {
		slogutil.Warn(r.Context(), "v2 advertise failed", slog.Any("error", err))
	}
	return true
}

